import (
	"fmt"
)

func main() {
	var h int
	var n uint64
	fmt.Scan(&h, &n)

	i := 0
	b := 0
	var k uint64
	var residue uint64 = n
	var branch uint64
	var side uint64
	var total uint64
	var leafs uint64 = 1
	line := true

	for i < h {
		leafs *= 2
		i++
	}

	side = leafs
	residue = n
	i = 0

	for i < h {
		side /= 2
		if residue >= 2 {
			if residue <= side {
				if line {
					line = !line
					total += 1
				} else {
					b = i
					k = 1
					branch = 0
					for b < h {
						branch += k
						k *= 2
						b++
					}
					total += branch + 1
				}
			} else {
				residue -= side
				if !line {
					line = !line
					total += 1
				} else {
					b = i
					k = 1
					branch = 0
					for b < h {
						branch += k
						k *= 2
						b++
					}
					total += branch + 1
				}
			}
		} else if residue == 0 {
			if !line {
				line = !line
				total += 1
			} else {
				b = i
				k = 1
				branch = 0
				for b < h {
					branch += k
					k *= 2
					b++
				}
				total += branch + 1
			}
		} else {
			if line {
				line = !line
				total += 1
			} else {
				b = i
				k = 1
				branch = 0
				for b < h {
					branch += k
					k *= 2
					b++
				}
				total += branch + 1
			}
		}
		i++
	}

	fmt.Println(total)
}

